window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-sindrome-dos-ovarios-policisticos"]={"block":"anki:ginecologia-sindrome-dos-ovarios-policisticos","label":"Anki · Síndrome dos Ovários Policísticos","count":90,"questions":[{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-2bdfae3527d54088","number":"0201e","sourceNumber":"0201e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 22 anos, queixa-se de longos períodos de atraso menstrual, chegando até a 3 meses, desde a menarca. Refere também acne e aumento de pelos em mento e região lateral da face. Já havia procurado auxílio médico há vários anos, porém foi informada de que a irregularidade era normal da idade. Menarca aos 13 anos. DUM: há 2 meses, costuma ter fluxo intenso e sem cólica. Sexarca aos 17 anos, com uso irregular de condom. Ao exame: IMC: 24, acne moderada e pelos pouco aumentados em face e abdome inferior. Exame ginecológico normal. A melhor conduta para esta paciente, diante da suspeita clínica seria:","options":{"A":"Prescrição de metformina 1500mg/dia, tendo em vista evitar complicações futuras decorrentes da síndrome metabólica.","B":"Prescrição de progesterona contínua para proteção endometrial, anticoncepção e preservação do futuro reprodutivo","C":"Prescrição de anticoncepcional oral contínuo com etinilestradiol + acetato de ciproterona para regularização dos ciclos, proteção endometrial, e melhora do hiperandrogenismo.","D":"Prescrição de Flutamida para tratamento dos sinais de hiperandrogenismo, que trazem as piores sequelas físicas e psicológicas para estas pacientes.","E":"Orientar inicialmente a mudança no estilo de vida com ênfase na perda de peso e sem tratamento medicamentoso, a princípio."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463097","ankiGuid":"lUX^mz|>SQ"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-5e4dbc26e04603f8","number":"0202e","sourceNumber":"0202e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A síndrome dos ovários policísticos (SOP) caracteriza-se primariamente por disfunção ovulatória e hiperandrogenismo, sendo o diagnóstico realizado após exclusão de outras causas para esses distúrbios. Assinale a alternativa que apresenta apenas diagnósticos diferenciais para SOP.","options":{"A":"Uso de anticoncepcional oral combinado, tumor secretor de androgênios e endometriose","B":"Hipotireoidismo, endometriose e insuficiência adrenal primária","C":"Hiperplasia adrenal congênita não clássica, hiperprolactinemia e síndrome de Cushing","D":"Hipertireoidismo, hipogonadismo e doença inflamatória pélvica","E":"Hiperprolactinemia, miomatose uterina e insuficiência ovariana primária"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463098","ankiGuid":"pjVF>zzr>j"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-8fd5ffa9e61c0a09","number":"0203e","sourceNumber":"0203e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 14 anos, com ciclos menstruais a cada 28 dias e 4 dias de fluxo, IMC de 25 kg/m² e 6 pontos na Escala Ferriman-Gallwey para hirsutismo, veio à consulta com laudo ultrassonográfico de ovários micropolicísticos. Diante da preocupação da paciente com o resultado do exame, o médico deve","options":{"A":"prescrever citrato de clomifeno associado a acetato de ciproterona.","B":"tranquilizá-la, dispensando qualquer investigação.","C":"confirmar o diagnóstico de síndrome dos ovários policísticos com dosagem sérica de TSH, FSH e LH.","D":"confirmar o diagnóstico de síndrome dos ovários policísticos com dosagem sérica de prolactina e 17-OH-progesterona.","E":"solicitar novo exame ultrassonográfico em 3 meses para confirmar o diagnóstico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463099","ankiGuid":"cM#vE^S9BR"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-b49f0dcc31eec7fa","number":"0204e","sourceNumber":"0204e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Uma paciente de 27 anos de idade, nuligesta, tentando engravidar há um ano e meio, queixa-se de acne, oleosidade da pele e aumento de pelos na face, confirmados no exame físico. Refere também que os ciclos menstruais geralmente são irregulares, com intervalos de até dois meses. Nega doenças crônicas conhecidas, uso de medicamentos e doenças familiares dignas de nota. Ao USG transvaginal, foi observado útero em medioversão, com volume de 60 cm³ , ovário direito com volume de 15 cm³ e ovário esquerdo com volume de 13 cm³ , sem descrição de folículos. Foi feita a dosagem sérica de androgênios (testosterona, androstenediona, DHEA e SDHEA) e todos se encontravam dentro dos limites da normalidade. Com base nessa situação hipotética, assinale a alternativa correta em relação à síndrome dos ovários policísticos (SOP).","options":{"A":"A avaliação de resistência insulínica faz parte dos critérios diagnósticos de SOP.","B":"A paciente não preenche os critérios para diagnóstico de SOP.","C":"O USG não é sugestivo de SOP, pois não foram vistos múltiplos folículos, porém os demais sintomas permitem fechar diagnóstico.","D":"Recomenda-se sempre iniciar o tratamento com anticoncepcional oral combinado para a remissão da doença antes de se liberar a paciente para engravidar.","E":"A metformina é utilizada para o tratamento e leva à melhora do padrão menstrual e à redução dos níveis dos androgênios, além de ter efeito positivo sobre a ovulação."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463100","ankiGuid":"dS^hR=Z%iI"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-fcfe9db523628202","number":"0205e","sourceNumber":"0205e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher de 25 anos, nuligesta, com disfunção menstrual desde a menarca, apresenta períodos de amenorreia de até 9 meses. Exame físico: PA 130x70 mmHg, estatura 1,50 m, peso 72 kg, acne ausente, índice de Ferriman--Gallwey (IFG) 10, acantosis nigricans presente na região cervical posterior. USG-TV: útero 52 cm³, espessura endometrial 6 mm, ovário direito 8,5 cm³, ovário esquerdo 7,0 cm³. A principal hipotese diagnóstica é","options":{"A":"síndrome dos ovários policísticos, devendo-se afastar outras etiologias que cursamcom disfunção menstrual e hiperandrogenismo.","B":"síndrome dos ovários policísticos e como apresenta acantosis nigricans não énecessário afastar outras etiologias.","C":"hiperplasia adrenal congênita, forma não clássica, pois a ultrassonografia é normal.","D":"hiperplasia adrenal congênita, forma não clássica, devido ao valor de IFG."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463101","ankiGuid":"mhk+>X.KAa"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-4ff2ea44987e54fe","number":"0206e","sourceNumber":"0206e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente com 19 anos, altura de 1,60 m, peso 84 kg, com histórico de ciclos oligomenorreicos, acne e hirsutismo. Em relação à sua principal hipótese diagnóstica, pode-se afirmar que","options":{"A":"apresenta redução na síntese de SHBG.","B":"raramente cursa com resistência insulínica.","C":"apresenta relação sérica de LH/FSH diminuída.","D":"os níveis androgênicos encontram-se diminuídos.","E":"não está associada com outros distúrbios metabólicos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463102","ankiGuid":"llSxHnnHUB"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-8923641ff3a86c95","number":"0207e","sourceNumber":"0207e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 26 anos, casada há 1 ano, sem uso de método anticoncepcional, com vida sexual normal, apresenta infertilidade decorrente de anovulação crônica hiperandrogênica. Sobre a indução de ovulação, é CORRETO afirmar:","options":{"A":"Nas pacientes resistentes ao citrato de clomifeno, a associação de metformina não melhora as taxas de ovulação.","B":"A droga de primeira escolha é o citrato de clomifeno.","C":"Nas usuárias de metformina, pelo risco de teratogênese, deve-se manter rigorosa vigilância.","D":"A cirurgia de Thaler é a melhor e a primeira opção.","E":"Gonadotrofinas não devem ser utilizadas, devido ao risco elevado de hiperestimulação ovariana."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463103","ankiGuid":"xF>>rPNCzC"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-194d8d0178c107dd","number":"0208e","sourceNumber":"0208e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A Síndrome dos Ovários Policísticos (SOP) acomete mulheres no mundo inteiro e cursa com quadro de hiperandrogenismo. Qual das afirmativas abaixo é CORRETA?","options":{"A":"A morfologia policística se deve ao estímulo da testosterona livre.","B":"Meninas com baixo peso ao nascer têm risco elevado de desenvolver SOP na adolescência.","C":"Pacientes com SOP não apresentam hiperinsulinismo compensatório, apenas resistência à insulina.","D":"A presença de acne é o melhor marcador físico para o diagnóstico de SOP na adolescência."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463104","ankiGuid":"jt9Bg5pJ=R"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-ce5a4c0a1e8910d9","number":"0209e","sourceNumber":"0209e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente com síndrome de ovários policísticos, apresenta ao exame físico acantose nigricans. Essa alteração está relacionada a:","options":{"A":"Hiperestrogenismo.","B":"Hipoestrogenismo.","C":"Hiperandrogenismo.","D":"Hipoandrogenismo.","E":"Resistência insulínica."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463105","ankiGuid":"qZdljKs+H9"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-325b972dcbe1bfdc","number":"0210e","sourceNumber":"0210e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Adolescente, 17 anos, apresenta menstruação irregular, pele oleosa, acne, dificuldade de perder peso. Iniciou anticoncepcional hormonal oral combinado, os ciclos menstruais ficaram regulares e teve melhora da acne. Pode-se atribuir a melhora da acne a qual efeito do anticoncepcional?","options":{"A":"Redução dos níveis de estradiol.","B":"Redução dos níveis de progesterona.","C":"Aumento da globulina carreadora de hormônio sexual (SHBG).","D":"Aumento da conversão de testosterona em diidrotestosterona.","E":"Aumento da testosterona livre."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463106","ankiGuid":"oOeDo::S*("},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-ab95e9911624ec74","number":"0211e","sourceNumber":"0211e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher, 18a, nuligesta, procura atendimento médico com ciclos menstruais irregulares de 90 -120 dias desde a menarca. Antecedente pessoal: menarca aos 11 anos. Exame físico: IMC= 26,7Kg/m², índice Ferriman-Gallwey= 9. PARA REALIZAR O DIAGNÓSTICO É NECESSÁRIO:","options":{"A":"Elevação sérica de insulina e teste de tolerância à glicose alterado.","B":"Presença da relação LH/FSH > 2 e medida da circunferência abdominal > 88 cm.","C":"Padrão menstrual de anovulação crônica e hiperandrogenismo clínico e/ou bioquímico.","D":"Aumento do volume ovariano com presença de folículos periféricos à ultrassonografia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463107","ankiGuid":"hU|Z?*F)3O"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-e0904e34287b40a7","number":"0212e","sourceNumber":"0212e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Com relação a síndrome dos ovários policísticos (SOP) assinale a alternativa ERRADA.","options":{"A":"Entre as teorias etiopatogênicas mais difundidas, associa-se a SOP ao aumento da frequência e pulsos do FSH, distúrbios da resposta das células tecais ao LH, resistência à insulina e aos fatores de crescimento similares a insulina.","B":"Os achados e manifestações clínicas são variados, destacando-se o hirsutismo, distúrbios menstruais, acne, obesidade, alopecia androgênica, infertilidade e acantose.","C":"Além das alterações relativas às gonadotrofinas, parece haver um papel significativo da insulina IGF-1 na produção anômala de androgênio nestas mulheres.","D":"A dosagem do TSH pode ser complementar na avaliação das pacientes com SOP, pois 14 a 20% delas apresentam valores aumentados deste hormônio e parece que esta alteração está relacionada ao pior perfil metabólico nestas pacientes.","E":"Os critérios ultrassonográficos padronizados segundo as recomendações da ASRM/ESHRE de 2018 são: a presença de 20 ou mais folículos com diâmetro médio de 2 a 9mm e/ou volume de 10cm³."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463108","ankiGuid":"RTW==Xm=o"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-b929c0ed24bd77c0","number":"0213e","sourceNumber":"0213e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"São consequências a longo prazo da Síndrome do ovário policístico:","options":{"A":"obesidade, infertilidade, mentruação irregular.","B":"dislipidemia, hirsutismo, acne.","C":"alopécia androgênica, intolerância à glicose, acantose nigricante.","D":"diabetes melito, câncer endometrial, doença cardiovascular.","E":"apneia obstrutiva do sono, amenorreia, atrofia ovariana."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463109","ankiGuid":"ch#$@c4LCp"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-47095d9cbfffde23","number":"0214e","sourceNumber":"0214e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente com hirsutismo de origem desconhecida; para diagnóstico dessa entidade solicitaremos dosagem sérica de:","options":{"A":"Androstenodiana e diidrotestosterona","B":"Testosterona e S-DHEA","C":"Androstenediol e progesterona","D":"Cetoesteróides e hidroxiesteróides","E":"Pregnanediol e estrona"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463110","ankiGuid":"twQjK#{uJo"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-010549957b80c69b","number":"0215e","sourceNumber":"0215e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Relacione os diagnósticos diferencias e sua propedêutica complementar do hiperandrogenismo: 1. Hiperprolactinemia; 2. Disfunções tireoidianas; 3. Tumor de adrenal; 4. Hiperplasia adrenal congênita; 5. Tumor ovariano produtor de progesterona; [ ] Dosagem de TSH; [ ] Dosagem de sulfato de deidroepiantrosterona; [ ] Dosagem de testosterona livre ou total; [ ] Dosagem de prolactina; [ ] Dosagem de 17-alfa-hidroxi- androgênio; Está correta a afirmativa com a sequencia:","options":{"A":"1, 2, 3 ,4 , 5","B":"3, 4, 5, 2, 1","C":"2, 4, 3, 1, 5","D":"2, 3, 5, 1, 4","E":"2, 4, 3, 5, 1"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463111","ankiGuid":"v/-qNNsLe>"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-72d44b387c2d6aec","number":"0216e","sourceNumber":"0216e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 20 anos, obesa, apresenta oligomenorréia e hirsutismo desde a puberdade. Sua avaliação laboratorial mostra prolactina, TSH e cortisol normais e, 17- hidroxiprogesterona elevada. O diagnóstico mais provável é:","options":{"A":"Anovulação crônica de causa hipotalâmica.","B":"Síndrome dos ovários policísticos.","C":"Hiperplasia adrenal na forma tardia.","D":"Tumor ovariano produtor de androgênio.","E":"Síndrome de Kallman."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463112","ankiGuid":"F*sGWfBdgR"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-e2b47d8148ba1933","number":"0217e","sourceNumber":"0217e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Em relação à síndrome dos ovários policísticos (SOP), atribua V (verdadeiro) ou F (falso) às afirmativas a seguir. ( ) A disfunção menstrual na SOP é caracterizada por oligomenorreia ou amenorreia. ( ) Os distúrbios menstruais têm, classicamente, um início peripuberal. ( ) A ausência de um nível sérico elevado de LH exclui o diagnóstico de SOP. ( ) As mulheres com SOP apresentam risco diminuído para abortamento espontâneo. ( ) Apneia do sono é comum em mulheres com SOP. Assinale a alternativa que contém, de cima para baixo, a sequência correta.","options":{"A":"V, V, F, F, V.","B":"V, F, V, V, F.","C":"V, F, V, F, F.","D":"F, V, V, F, V.","E":"F, V, F, V, V."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463113","ankiGuid":"G=S3VL#[?~"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-54d167968cfce456","number":"0218e","sourceNumber":"0218e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"O uso de anticoncepcionais hormonais orais combinados em pacientes com a Síndrome dos Ovários Policísticos:","options":{"A":"diminui a chance de gravidez futura.","B":"diminui os níveis de SHBG (globulina carreadora dos hormônios sexuais.","C":"diminui o risco de câncer de mama.","D":"diminui a resistência a insulina.","E":"diminui o risco de hiperplasia endometrial."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463114","ankiGuid":"dUo;e*|P,-"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-72c90e635b4362a7","number":"0219e","sourceNumber":"0219e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Bruna, 33 anos, casada, nuligesta, com ciclos menstruais infrequentes até 29 anos, que foram regularizados depois. Está sem êxito em engravidar há 2 anos e 6 meses. Foi diagnosticada com Síndrome dos Ovários Policísticos (SOP). Sem alterações nos exames do marido. Considere as assertivas sobre infertilidade na SOP a seguir e assinale a alternativa CORRETA. I. O letrozol reduz a conversão de androgênios em estrogênios nas células da granulosa, aumenta a liberação de gonadotrofinas e subsequente estimulação ovariana. II. Distúrbios endócrino-metabólicos, como hiperandrogenismo e hiperinsulinemia, pioram a fertilidade nas pacientes com SOP. III. Podemos afirmar que há dificuldade para engravidar, já que a ovulação ocorre em menos de 10% dos ciclos. IV. Em razão dos distúrbios anovulatórios frequentemente, cursa com infertilidade.","options":{"A":"Apenas I e III.","B":"Apenas II, III e IV.","C":"Apenas II e IV.","D":"Apenas I, III e IV.","E":"Apenas I, II e IV."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463115","ankiGuid":"Nc*sUs.e|O"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-3b8916db58bca25c","number":"0220e","sourceNumber":"0220e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Jovem de 18 anos queixa-se de amenorréia. Nega coitarca. Exame físico: observa-se pele acneica, hirsutismo e presença de acantose nigricante. Ultrassonografia pélvica evidencia ovários de volume aumentado, ambos maiores que 10 mL, o ovário esquerdo 13 microcistos de até 9 mm de diâmetro e o direito com 14 microcistos de até 9 mm de diâmetro. Com base no quadro clínico é correto afirmar que:","options":{"A":"o diagnóstico é síndrome dos ovários policísticos, devendo-se iniciar o tratamento com anticoncepcionais contendo ciproterona.","B":"é necessário excluir outras causas de hiperandrogenismo e/ou anovulação.","C":"deve-se prescrever prednisona pois o quadro é bem característico de síndrome de Cushing.","D":"para os critérios de ovários policísticos deve-se ter pelo menos 7 microcistos com até 9 mm de diâmetro.","E":"não há sinais de resistência insulínica neste quadro clínico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463116","ankiGuid":"y!=MNaVw{F"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-908a2d1d210cad0f","number":"0221e","sourceNumber":"0221e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Síndrome de Ovários Policísticos (SOP) é uma doença endocrinometabólica multifatorial, sem etiologia definida. Em relação à SOP, é correto afirmar:","options":{"A":"Tem nos anticoncepcionais hormonais orais sua primeira linha de tratamento, afastando fatores de riscos associados.","B":"O hiperandrogenismo é a manifestação menos comum na SOP, acometendo um seleto e restrito número de pacientes.","C":"Na classificação de PALM_COEN, o sangramento uterino anormal provocado pela SOP é definido como sangramento estrutural.","D":"A abordagem dos distúrbios metabólicos provocados pela SOP desconsidera alterações de hábitos de vida, perda de peso, atividade física e cirurgia bariátrica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463117","ankiGuid":"Cso&NU?iAz"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-87ac96ae0d12115e","number":"0222e","sourceNumber":"0222e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher de 23 anos procura o ginecologista por causa de hirsutismo, surgido na adolescência. Teve menarca aos 14 anos, com menstruações posteriores sempre irregulares. No momento, está há 5 meses sem menstruar. Não deve ser o diagnóstico da paciente:","options":{"A":"Tumor ovariano.","B":"Endometriose.","C":"Síndrome dos ovários policísticos.","D":"Hiperplasia adrenal congênita não clássica.","E":"Tumor na suprar renal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463118","ankiGuid":"w|Y]|fIj}"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-89bb0d0b72512fe5","number":"0223e","sourceNumber":"0223e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 26 anos, nuligesta, vida sexual ativa, vem à consulta se queixando de fluxo menstrual excessivo há 10 dias. Ao exame clínico foi observado mucosas levemente hipocoradas e hidratadas, presença de pelos em região de mento e bulso. PA: 110 x 80 mmHg. Relata que seus ciclos são irregulares desde a adolescência. Estava sem menstruar há seis meses e a última menstruação durou apenas 3 dias com baixo fluxo. Realizou exame de gravidez (dosagem qualitativa de beta hCG) por conta própria cinco dias antes de menstruar com resultado negativo, mesmo usando preservativo em todas as relações. Peso atual: 78 Kg. Altura: 1,55 m. Em ltrassonografia transvaginal realizada há 11 meses foi detectado ovários com volume aumentado e presença de folículos dispersos na periferia dos ovários (padrão micropolicísticos). No caso descrito está correto afirmar que","options":{"A":"A hipermenorréia se deve pelo baixo nível de estrogênio e FSH, e alto nível de LH e progesterona.","B":"No período de amenorreia o padrão histológico do endométrio é do tipo secretor devido altos níveis de progesterona.","C":"O nível elevado de LH está estimulando maior produção de androgênios nas células da teca no ovário.","D":"A dosagem de testosterona sérica é necessária para o diagnóstico de síndrome dos ovários policísticos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463119","ankiGuid":"EcaIF3~^op"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-18c9432c453b5ccb","number":"0224e","sourceNumber":"0224e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 20 anos de idade, obesa, apresenta oligomenorreia e hirsutismo desde a puberdade. Sua avaliação endocrinológica laboratorial mostra prolactina normal, TSH normal, cortisol normal e 17-hidroxiprogesterona elevada. A hipótese diagnóstica para o quadro é a","options":{"A":"síndrome dos ovários policísticos.","B":"anovulação crônica hipotalâmica.","C":"hiperplasia adrenal congênita na forma tardia.","D":"síndrome da sela vazia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463120","ankiGuid":"g4vkw8&>`*"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-d6dbf838c5d4f1e0","number":"0225e","sourceNumber":"0225e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"O índice de Ferriman-Gallwey é utilizado para","options":{"A":"contagem de microcistos nos ovários.","B":"classificar amenorreia.","C":"avaliar grau de disfunção ovariana.","D":"classificar hirsutismo.","E":"classificar infertilidade."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463121","ankiGuid":"w1*jw7T):["},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-075c0ce588896de3","number":"0226e","sourceNumber":"0226e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 22 anos, com ciclos oligomenorreicos desde a menarca, acne e hirsutismo, em que a avaliação laboratorial mostra LH (Hormônio Luteinizante) duas vezes o valor do FSH (Hormônio Folículo Estimulante) e índice de HOMA (Homeostatic Model Assessment) compatível com hiperinsulinemia. O provável diagnóstico é:","options":{"A":"Síndrome do ovário policísticos (anovulação crônica).","B":"Hiperplasia adrenal congênita.","C":"Tumor ovariano produtor de androgênios.","D":"Tumor de células da granulosa."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463122","ankiGuid":"gSzG7W0M8r"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-07ed5310c7a751ea","number":"0227e","sourceNumber":"0227e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Uma mulher de 22 anos de idade procurou o serviço de saúde com queixa de irregularidade menstrual, associada a hiperandrogenismo (acne e hisurtismo). Sua ultrassonografia apresentou útero com volume normal, eco endometrial sem alterações e ovários com volumes aumentados e padrão policístico.","options":{"A":"caso a paciente em questão não apresentasse irregularidade menstrual, o diagnóstico da síndrome dos ovários policísticos ainda poderia ser considerado.","B":"o critério ultrassonográfico é considerado como positivo na presença de ambos os ovários alterados. Caso a paciente em questão apresentasse apenas um ovário alterado, esse critério não seria positivo.","C":"o hiperandrogenismo é obrigatório para o diagnóstico da síndrome dos ovários policísticos.","D":"trata-se de paciente jovem. Sendo assim, não há a necessidade de se excluir outras patologias antes da confirmação de que ela tem o diagnóstico da síndrome dos ovários policísticos.","E":"a presença de acne só será valorizada caso a paciente apresente androgênios séricos aumentados."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463123","ankiGuid":"L0dE_uOqjv"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-4a10692e7569844a","number":"0228e","sourceNumber":"0228e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher 19 anos com menarca aos 11, evoluindo com ciclos menstruais irregulares com longos períodos de amenorreia seguido de fluxo menstrual intenso, queixa-se ainda de acne severo, excesso de pelos e dificuldade de emagrecer. Procurou assistência médica na UBS e foi diagnosticada como tendo síndrome dos ovários micropolicísticos (SOMP). Assinale a assertiva correta sobre o diagnóstico e achados clínicos de SOMP.","options":{"A":"Devido ao hiperandrogenismo, sinais de virilização, como aumento da massa muscular, redução das mamas, e clitoromegalia, são típicos da SOMP.","B":"A acne vulgar é achado clínico muito frequente em adolescentes, portanto, a acne persistente ou de início tardio não sugere diagnóstico de SOMP.","C":"A anovulação pode resultar de resistência insulínica e grande parte das pacientes com SOMP retomam os ciclos ovulatórios após iniciar metformina.","D":"Os níveis androgênicos normalmente estão elevados na SOMP e os níveis de progesterona são também elevados em razão dos ciclos anovulatórios."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463124","ankiGuid":"zVehv`c!+O"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-af2beb1479ef791b","number":"0229e","sourceNumber":"0229e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Não representa um benefício do uso da Metformina em pacientes com Síndrome dos Ovários Policísticos:","options":{"A":"facilita a perda de peso.","B":"aumenta a chance de ovulação.","C":"diminui cólicas intestinais.","D":"diminui os níveis de colesterol e triglicérides."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463125","ankiGuid":"z}3j)D:K<0"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-1d358a4648ffb5ae","number":"0230e","sourceNumber":"0230e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 28 anos, G₂P₂A₀ (1 Parto normal e 1 Cesariana com LT, anteriores), última menstruação há 4 meses, nega uso de qualquer medicação, comparece à UBS, sendo examinada (Ferriman=12), trazendo os seguintes resultados de exames, realizados há uma semana: FSH= 7,5 mUI/ml, Beta-HCG sérico negativo, Prolactina= 12 ng/dL, TSH= 2,5mUI/L, Testosterona total= 97ng/dL e SDHEA= 155ng/dL . Nesta situação, a conduta correta é:","options":{"A":"Iniciar imediatamente anticoncepção com pílula combinada, devido ao FSH baixo;","B":"Prescrever Terapia de Reposição Hormonal imediatamente, utilizando-se da medicação disponível na UBS;","C":"Solicitar ultra-sonografia apenas, para avaliar o endométrio;","D":"O quadro clínico é compatível com anovulação crônica, por síndrome dos ovários policísticos e o tratamento pode ser somente progestágeno 14 dias por mês, iniciando no 12º dia do ciclo.","E":"Repetir os exames em uma semana, adicionando ao pedido, as dosagens de LH e Progesterona."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463126","ankiGuid":"u^=FX3V(0)"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-294cc799029ac142","number":"0231e","sourceNumber":"0231e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 22 anos queixa-se de longos períodos de atrasos menstruais, desde a menarca. Refere também acne e aumento de pelos em mento e região lateral da face. Já havia procurado auxílio médico há vários anos, porém foi informada de que a irregularidade era normal da idade. Menarca aos 13 anos. DUM: há 2 meses, costuma ter fluxo intenso e sem cólica. Sexarca aos 17 anos, com uso irregular de preservativo. Ao exame: IMC: 25, acne moderada e pelos pouco aumentados em face e abdome inferior. Exame ginecológico normal. Assinale a melhor alternativa diante do caso exposto:","options":{"A":"A principal suspeita é de Hiperprolactinemia. Assim sendo, solicitaria ultrassonografia transvaginal, dosagem de Prolactina, e prescreveria drogas dopaminérgicas para tratamento clinico.","B":"A principal suspeita é de Síndrome de ovários policísticos (SOP). Assim sendo, solicitaria ultrassonografia transvaginal, dosagens hormonais para diagnóstico de exclusão, teste oral de tolerância à glicose para avaliar resistência insulínica, prescreveria anticoncepcional oral combinado com maior ação antiandrogênica.","C":"A principal suspeita é de sangramento uterino disfuncional. Solicitaria ultrassonografia transvaginal, dosagens hormonais, e prescreveria anticoncepcional oral combinado com maior ação antiandrogênica.","D":"A principal suspeita é de hiperplasia suprarrenal de forma tardia. Assim sendo solicitaria ultrassonografia transvaginal, dosagens hormonais, prescreveria corticoide sistêmico associado a anticoncepcional oral combinado com maior ação antiandrogênica.","E":"A principal suspeita é de SOP. Assim sendo, solicitaria ultrassonografia transvaginal, dosagens hormonais para diagnóstico de exclusão, TTOG para avaliar resistência insulínica, prescreveria metformina, uma vez que atualmente a hiperinsulinemia possui papel de destaque na SOP."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463127","ankiGuid":"x4}^`<-N.9"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-ef04c86b04c2216d","number":"0232e","sourceNumber":"0232e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher, 27 anos, refere aumento de oleosidade e acne, além de ciclos menstruais alternando com episódios de amenorréia. Apresenta dislipidemia, glicemia jejum normal e obesidade. Em uso de anticoncepcional oral combinado há 3 meses. Qual a melhor conduta para essa paciente?","options":{"A":"Parar o uso do anticoncepcional e indicar tratamento com azitromicina dose diária por 30 dias.","B":"Solicitar FSH, LH e SHBG para avaliar se houve falha do tratamento clínico.","C":"Orientar perda de peso e praticar exercícios físicos .","D":"Trocar anticoncepcional por falha do tratamento e indicar DIU de levonogestrel.","E":"Iniciar clonidina em associação"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463128","ankiGuid":"MN;5<mT:fp"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-8f56b22e9b5d9f1f","number":"0233e","sourceNumber":"0233e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Uma mulher de 31 anos de idade, nuligesta, procurou o serviço de ginecologia endócrina com o diagnóstico da síndrome dos ovários policísticos (SOP) e queixando-se de hiperandrogenismo. Foi introduzida pílula combinada. Não há antecedentes familiares dignos de nota. Com base nesse caso hipotético, assinale a alternativa correta.","options":{"A":"O etinilestradiol, quando metabolizado em nível hepático, resulta no aumento da SHBG (sex hormone-binding globulin), o que acarreta a diminuição da testosterona livre.","B":"As pílulas que contêm hormônios naturais apresentam maior eficácia no tratamento do hiperandrogenismo em pacientes com SOP.","C":"O etinilestradiol da pílula cursa com um feedback positivo sobre o hormônio luteinizante, pois resulta na diminuição da síntese de androgênios no ovário.","D":"A pílula combinada acarreta a inibição da enzima aromatase, responsável pela conversão do estrogênio em testosterona.","E":"As pílulas contraceptivas que contêm apenas progestógenos apresentam maior eficácia na redução do hiperandrogenismo que as pílulas combinadas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463129","ankiGuid":"gP}#:*U*l8"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-240c6e2d2ca9c78f","number":"0234e","sourceNumber":"0234e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"O padrão hormonal mais encontrado na síndrome dos ovários policísticos é:","options":{"A":"FSH elevado, LH baixo, testosterona normal e estrona baixa","B":"FSH elevado, LH elevado, testosterona baixa e estrona baixa","C":"LH menor que FSH, testosterona e estrona baixos","D":"LH maior que FSH, testosterona e estrona elevados","E":"LH e FSH baixos, testosterona e estrona elevados."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463130","ankiGuid":"GdBO1X3^~m"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-36f5cc0a9ae29cd1","number":"0235e","sourceNumber":"0235e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Menina de 16 anos queixa-se de pele oleosa e acne, principalmente em face, acompanhada de aumento e pilificação pelo corpo desde o início dos ciclos menstruais. Teve telarca e pubarca aos 10 anos e menarca aos 13 anos. Apresenta ciclos menstruais com intervalos entre 40 a 90 dias. Nega coitarca. Nega comorbidades e não há relato de doenças crônicas na família. Exame físico: IMC = 23 kg/m², PA = 100 x 80 mmHg, mucosas coradas, acne em face e região do dorso, Índice de Ferriman = 9. Desenvolvimento dos caracteres sexuais: mamas M5 e pelos P5. Genitália externa feminina, com hímen íntegro e sem anormalidades. Exames complementares colhidos no 3ª dia do ciclo menstrual: FHS = 5,6 Ul/ml (VN: 2,8 a 14,4 mlU/mL); testosterona = 98 ng/dL (VN: 20 a 80 ng/dL); 17 OH Progesterona = 156 ng/dL (VN: 30 a 200 ng/dL); Prolactina = 10 ng/mL (VN: 5-25 ng/mL); TSH = 2,8 mU/L (VN: 0,3 a 4,0 mU/L) , Glicemia de 85 mg/dL. Qual a primeira opção de tratamento?","options":{"A":"Metformina.","B":"Isotretinoina.","C":"Anticoncepcional de progesterona.","D":"Anticoncepcional hormonal combinado."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463131","ankiGuid":"w,>DLEj@&X"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-33489b98f9563142","number":"0236e","sourceNumber":"0236e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Segundo a teoria de duas células, proposta para explicar a produção de esteroides sexuais pelo folículo ovariano e sua relação com os efeitos da pílula anticoncepcional combinada no tratamento da síndrome dos ovários policísticos, é correto dizer que:","options":{"A":"O bloqueio da liberação hipofisária de FSH, promovida pela pílula, leva à maiorprodução da globulina transportadora de esteroides sexuais (SHBG), levando à menor secreção de androgênios pelo ovário.","B":"O bloqueio da liberação hipofisária de FSH, promovida pela pílula, leva à menorprodução androgênica pelas células da granulosa no ovário.","C":"O bloqueio da liberação hipofisária de LH, promovida pela pílula, leva à menor produção androgênica pelas células da teca no ovário.","D":"A ação direta da pílula no folículo ovariano promove menor atividade da enzima aromatase, com consequente redução da produção androgênica ovariana."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463132","ankiGuid":"FX,tFmSAq1"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-08b94b6d977481af","number":"0237e","sourceNumber":"0237e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 19 anos apresenta menstruações a cada 90 dias desde a menarca. Apresentou menarca aos 11 anos, G0P0. Ao exame físico: IMC = 26,7, índice Ferriman- Gallwey = 10. O diagnóstico de síndrome dos ovários policísticos é possível com:","options":{"A":"Alteração da morfologia ovariana à ultrassonografia, uma vez que este é critério indispensável.","B":"Altos níveis de 17 hidroxiprogesterona.","C":"Avaliação do padrão menstrual de anovulação crônica e presença de hiperandrogenismo clínico e/ou bioquímico.","D":"Alteração laboratorial no valor da insulina e no teste de tolerância à glicose.","E":"Presença da relação LH/FSH > 2 e de obesidade central, com medida da circunferência da cintura > 88 cm."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463133","ankiGuid":"m(rGTy|^1/"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-7fd3347eadf783ea","number":"0238e","sourceNumber":"0238e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Sobre a Síndrome dos Ovários Policísticos (SOP) assinale a alternativa ERRADA:","options":{"A":"A etiopatogenia permanece pouco conhecida, mas estudos têm demonstrado ser poligênica e multifatorial.","B":"O diagnóstico é simples, não havendo necessidade da realização de exames laboratoriais.","C":"Tem relação estreita com resistência insulínica e o uso de metformina está autorizado na presença das complicações metabólicas da doença.","D":"O hormônio Anti-Mülleriano tem correlação positiva com número de folículos ovarianos pré-antrais, e poderia auxiliar no diagnóstico.","E":"Metformina é uma boa opção em uma paciente com SOP na presença de irregularidade menstrual quando o contraceptivo oral não é tolerado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463134","ankiGuid":"w+^.eWQG*D"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-308113585c92f48a","number":"0239e","sourceNumber":"0239e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A síndrome dos ovários policísticos é uma alteração frequente em mulheres e reúne vários achados clínicos e laboratoriais. Qual das alternativas abaixo NÃO é um critério diagnóstico essencial?","options":{"A":"Hiperandrogenismo.","B":"Ovário micropolicístico e/ou aumentado de volume (> 10 ml).","C":"Anovulação crônica.","D":"LH elevado."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463135","ankiGuid":"NFEf][s.co"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-b1e1fd2409efa10e","number":"0240e","sourceNumber":"0240e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Na síndrome dos ovários policísticos, é critério diagnóstico:","options":{"A":"hiperinsulinemia","B":"hipertrigliceridemia","C":"dosagem de LH maior do que FSH","D":"sinais clínicos de hiperandrogenismo"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463136","ankiGuid":"GG,$r:Vtl@"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-975216bc07771063","number":"0241e","sourceNumber":"0241e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher de 18 anos, refere ciclos menstruais a cada 3-4 meses, desde os 14 anos. O médico diagnosticou hiperplasia virilizante da suprarrenal. O exame que possibilitou identificar esta etologia foi:","options":{"A":"Dosagem da testosterona total.","B":"Dosagem da 17 OH Progesterona.","C":"Ultrassonografia pélvica.","D":"Dosagem da androstenediona.","E":"Ressonância magnética da suprarrenal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463137","ankiGuid":"ql?C#LiuIF"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-f54e4d29d281dd6f","number":"0242e","sourceNumber":"0242e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Clarice recebeu diagnóstico de SOP aos 25 anos de idade, mas seguiu com tratamento irregular. Marque a opção que representa uma complicação tardia da SOP.","options":{"A":"Câncer de endométrio.","B":"Osteoporose.","C":"Câncer de ovário.","D":"Gravidez múltipla."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463138","ankiGuid":"e4PKYVk90H"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-5a3682547b3be806","number":"0243e","sourceNumber":"0243e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Clarice de 25 anos procura atendimento com queixa de acne, oleosidade da sua pele e aumento de pêlos na face, confirmados no exame físico. Ciclos menstruais irregulares com intervalos de até 90 dias. Não tem vida sexual. Foi solicitada ultrassonografia pélvica que estava normal. Os níveis séricos dos androgênios testosterona, androstenediona, DHEA e SDHEA, 17 OH progesterona, TSH, prolactina, encontravam dentro do limite da normalidade. O médico que a atendeu fez diagnóstico de síndrome dos ovários policísticos (SOP). Masque a opção VERDADEIRA.","options":{"A":"Clarice não preenche o critério para diagnóstico de SOP, pois não foram vistos micropolicistos ovarianos e os androgênios séricos estavam normais.","B":"SOP está associada com sangramento uterino aumentado por miomatose ou por adenomiose.","C":"a SOP é uma causa de amenorreia secundária por hipogonadismo hipogonadotrófico.","D":"a pílula combinada é um tratamento reconhecido para a SOP, agindo por vários mecanismos, entre eles, a redução de níveis de LH."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463139","ankiGuid":"D_vk/lX!3N"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-87ecf411897e3b9f","number":"0244e","sourceNumber":"0244e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente com 28 anos de idade, solteira, apresentando ciclos menstruais irregulares há 2 anos, queixa-se de pele oleosa, pelos no rosto e nos membros inferiores. Tem atividade sexual e utiliza preservativo como método contraceptivo. Tem IMC (índice de massa corpórea) de 32. Traz os seguintes exames: LH 18 mUI/ml, FSH 5,8 mUI/ml, TSH 4 mU/L, glicemia de jejum 91 mg/dl, insulina basal 30 mU/L. Exame físico: paciente tem acne na face, pele oleosa e pelos na região do queixo e nos membros inferiores. Paciente deseja obter melhora das queixas clínicas e apresentar ciclos menstruais regulares. Levando em consideração os dados apresentados, deve-se orientar perda de peso, dieta hipocalórica e prescrever:","options":{"A":"Espironolactona 50 mg via oral duas vezes ao dia.","B":"Etinilestradiol 0,03 mg/dia + 0,15 mg/dia de levonorgestrel.","C":"Etinilestradiol 0,05 mg/dia + 0,15 mg/dia de drospirenona.","D":"3 mg de drospirenona e 0,03 mg de etinilestradiol.","E":"Espironolactona 100 mg ao dia + acetado de ciproterona 25 mg/dia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463140","ankiGuid":"rY(=R::wV4"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-1994bf868db3e985","number":"0245e","sourceNumber":"0245e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Adolescente, 16 anos de idade, procura atendimento pedindo prescrição de pílula anticoncepcional para tratar de acne em rosto, que sua tia, técnica em enfermagem, disse-lhe que era causada por ovário policístico. Menarca 11 anos, ciclos menstruais normais em intervalo, quantidade e duração. Sexarca há oito meses e nega comorbidades. Ao exame físico IMC 22,78, acne vulgaris moderada em face, principalmente na testa, distribuição pilosa corpórea normal. Sobre o síndrome de anovulação crônica hiperandrogênica estão corretas as seguintes afirmações: I. É quadro que, na maioria das vezes, tem início na puberdade. II. A paciente do presente caso apresenta dois dos critérios de Roterdan para o diagnóstico definitivo. III. Na maioria das vezes as portadores deste síndrome apresentam resistência à insulina e diabete tipo II. IV. A maioria das portadoras apresentam intervalos menstruais alongados, obesidade e grau variával de manifestações hiperangrogênicas. V. O tratamento indicado para a maioria das pacientes é a associação de metformina e anticoncepcional combinado com ciproterona. A seguinte alternativa contempla ao solicitado no enunciado:","options":{"A":"Apenas I, II e III.","B":"Apenas II, III e IV.","C":"Apenas III e V.","D":"Apenas III, IV e V.","E":"Apenas I e IV."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463141","ankiGuid":"C]AuW(>N}|"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-11add64dd9069204","number":"0246e","sourceNumber":"0246e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Em relação a Síndrome dos ovários policísiticos (SOP) podemos afirmar que: I. O aumento do LH em relação ao FSH estímula as células da teca folicular, as quais produzem um excesso de androstenediona; II. A SOP é pouco frequente na população feminina e não apresenta repercussões além de sintomas ginecológicos; III. Dentre as opções de tratamento dos sintomas androgênicos estão a ciproterona e a espironolactona; IV. Obesidade, síndrome metabólica, hirsutismo, oligomenorréia e amenorréia são condições pouco frequentes em pacientes com síndrome dos ovários microcísticos; V. Nas mulheres que não desejam gestar os anticoncepcionais orais são uma opção para o tratamento da SOP. Já nas mulheres que desejam gestar poder ser necessário o uso do citrato de clomifeno.","options":{"A":"I, III, e V estão corretas.","B":"III, IV e V estão corretas.","C":"I, II, e IV estão corretas.","D":"I, II, e III estão corretas.","E":"I, III, E IV estão corretas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463142","ankiGuid":"s(jtn]WEbK"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-62836b4e78b7edf0","number":"0247e","sourceNumber":"0247e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Jovem mulher de 20 anos, G0P0, procura o serviço de saúde, por apresentar irregularidade menstrual há três anos. Afirma ter ficado até seis meses sem menstruar em duas oportunidades. Ao exame, observa-se sobrepeso, presença de pelos em região do mento, sulco inter mamário e região lombar, além de acanto sisnigricans na parte posterior do pescoço. Traz consigo exames laboratoriais (testosterona total e androstenediona aumentadas e SHBG diminuído) e ecografia revelando ovários de 14 cm³ com 15 folículos periféricos de 10 mm cada. Considerando o diagnóstico acima, assinale a alternativa que melhor expressa a condição hiper androgênica.","options":{"A":"Acantosisnigricans","B":"Testosteronasérica total","C":"Índice de Ferriman Gallwey","D":"Fórmula de Vermeulen","E":"Sobrepeso e dislipidemia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463143","ankiGuid":"f97&IG!`_]"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-d7a9abb116d1cd4b","number":"0248e","sourceNumber":"0248e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 20 anos comparece a consulta em busca de orientação contraceptiva. Informa que ainda não iniciou atividade sexual, mas deseja iniciar um método, pois já está namorando há algum tempo. Relata ganho de peso recente, irregularidade menstrual e queixa-se de aparecimento frequente de acne nas costas e na face. Ao exame físico, presente hirsutismo leve em face e abdome e acnes sem outras alterações. Em relação a essa paciente, assinale a MELHOR conclusão:","options":{"A":"Ela ainda não iniciou a atividade sexual e tem forte suspeita de anovulação crônica, não estando recomendada a contracepção hormonal.","B":"Ela deve iniciar o rastreio para câncer de colo uterino com 25 anos de idade independentemente de atividade sexual.","C":"O uso de contraceptivos hormonais combinados não está recomendado em virtude da necessidade de investigação do ganho de peso.","D":"O uso de medroxiprogesterona injetável trimestral pode ser uma opção, mas a adesão da paciente ao método pode ser comprometida pela retenção hídrica característica do método."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463144","ankiGuid":"f[%^~2YRS("},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-d7c60bdd5086f5c8","number":"0249e","sourceNumber":"0249e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A irregularidade menstrual associada a sinais clínicos de hiperandrogenismo são queixas frequentes no consultório médico. Na avaliação dos quadros de hiperandrogenismo e na Síndrome do Ovário Policístico (SOP), é CORRETO afirmar que:","options":{"A":"A simples identificação de ovários policísticos à ultrassonografia (US) confirma o diagnóstico de SOP.","B":"Para diagnóstico da SOP, é obrigatória a presença dos três critérios: hiperandrogenismo clínico, presença de ovários policísticos ao US e irregularidade menstrual.","C":"A hiperplasia congênita da suprarrenal é um diagnóstico diferencial nos casos de SOP refratários ao tratamento clínico.","D":"A dosagem sérica de LH, FSH e TSH, no 3º dia do ciclo, é obrigatória para correto diagnóstico da SOP."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463145","ankiGuid":"jl7$j[WGf("},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-eaf13e9b1dda32d4","number":"0250e","sourceNumber":"0250e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"No diagnóstico diferencial do hirsutismo, se decorrente da síndrome dos ovários micropolicísticos ou das suprarrenais, é fundamental a dosagem de","options":{"A":"pregnenolona.","B":"ACTH.","C":"testosterona.","D":"17-hidroxiprogesterona."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463146","ankiGuid":"B[h`KzmPPZ"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-c91fdd750ab01fe2","number":"0251e","sourceNumber":"0251e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Jovem de 19 anos, menarca aos 13 anos, refere ter ovários polimicrocisticos. Para este diagnóstico ser estabelecido, segundo os critérios de Rotterdam, quais características devem estar presentes?","options":{"A":"Ecografia apresentando ovário aumentado de tamanho (maior que 10cm³) ou multifolicular (mais de 12 folículos pequenos).","B":"Duas das três características a seguir: irregularidade menstrual, ecografia com ovário multifolicular ou aumento do volume, hirsutismo ou acne.","C":"As três características a seguir: irregularidade menstrual, ecografia com ovário multifolicular ou aumento do volume, hirsutismo ou acne.","D":"Nesta idade o diagnóstico de SOP não existe e o diagnóstico correto é imaturidade axial.","E":"Amenorreia hipotalâmica, hiperprolactinemia, hirsurtismo."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463147","ankiGuid":"zK(fpByHTV"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-3d1de964c628d272","number":"0252e","sourceNumber":"0252e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher de 24 anos procura consultório médico com história de ciclos menstruais longos desde a menarca, chegando a passar até 6 meses sem sangrar. Ao exame físico, apresenta Índice de Massa Corpórea (IMC) 28 kg/m², acne moderada e hirsutismo. Qual a conduta mais adequada?","options":{"A":"Iniciar metformina 1g/dia para controle dos ciclos menstruais e hirsutismo.","B":"Orientar teste de progesterona para descartar causas uterinas de amenorreia.","C":"Dosar TSH, prolactina e 17-hidroxiprogesterona para descartar patologias sistêmicas.","D":"Iniciar anticoncepcional oral com ciproterona pelo diagnóstico de síndrome de ovários micropolicísticos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463148","ankiGuid":"wIc(9okw**"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-14b5c79bb9b4f5a5","number":"0253e","sourceNumber":"0253e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A Síndrome dos Ovários Policísticos é achado comum em pacientes inférteis e com ciclos oligomenorreicos. Paciente com quando de infertilidade e ciclos oligomenorréicos, após a investigação, foi confirmado o diagnóstico de Síndrome dos Ovários Polimicrocísticos (ou Policísíticos). Diante do desejo iminente de gestação, está indicado o uso de qual substância adjuvante na terapêutica visando a gravidez?","options":{"A":"Ciproterona.","B":"Desogestrel.","C":"Metformina.","D":"Drospirenona.","E":"Gestodeno."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463149","ankiGuid":"CqW%7P%m(d"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-5ebf19c2d19f1938","number":"0254e","sourceNumber":"0254e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente com 25 anos de idade, com vida sexual ativa, não desejando engravidar no momento, procura o ginecologista com quadro clínico e laboratorial de anovulação crônica. Assinalar o TRATAMENTO IDEAL para essa paciente:","options":{"A":"Anticoncepcional oral combinado","B":"Citrato de Clomifeno","C":"DIU T de cobre","D":"Progesterona cíclica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463150","ankiGuid":"Rb:&W?ddCb"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-086c92ad76785869","number":"0255e","sourceNumber":"0255e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher de 18 anos apresenta menstruações a cada 90-120 dias desde a menarca. AP: menarca aos 11 anos; G0P0. EF: IMC = 26,7; índice Ferriman-Gallwey = 9. Para realizar o diagnóstico de síndrome dos ovários policísticos, é necessário (a):","options":{"A":"Alteração laboratorial no valor da insulina e no teste de tolerância à glicose.","B":"Presença da relação LH/FSH > 2 e de obesidade central, com medida da circunferência da cintura > 88 cm.","C":"Avaliar o padrão menstrual de anovulação crônica e presença de hiperandrogenismo clínico e/ou bioquímico.","D":"Alteração da morfologia ovariana à ultrassonografia, uma vez que este é critério indispensável."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463151","ankiGuid":"pvU]^M[5l?"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-95216e0841491006","number":"0256e","sourceNumber":"0256e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Uma paciente de 22 anos de idade procurou serviço de ginecologia endócrina com quadro de irregularidade menstrual associado a hirsutismo. Além disso, refere escurecimento da pele em região de axilas e de pescoço. Apresenta TSH e FSH normais; LH elevado; testosterona total; SDHEA e 17-OH-progesterona dentro da normalidade, além de duas glicemias de jejum com o valor de 135 mg/dl. Na ultrassonografia transvaginal, útero em anteversoflexão com volume normal e ovários com volume aumentado (14 cm³ e 15 cm³) à custa de múltiplos folículos antrais. Com base nesse caso hipotético, assinale a alternativa CORRETA:","options":{"A":"Deve-se prescrever progesterona de segunda fase, visto que sua eficácia no controle do ciclo e na terapêutica do hiperandrogenismo é superior à da pílula combinada.","B":"Deve-se prescrever pílula combinada e metformina.","C":"A paciente apresenta um tumor ovariano secretor de testosterona, sendo indicado o tratamento cirúrgico.","D":"A primeira linha de tratamento medicamentoso é constituída pelo uso da espironolactona, que irá regularizar o ciclo menstrual e melhorar o hirsutismo.","E":"Deve-se prescrever pílula combinada e orientar alterações no estilo de vida para a perda de peso."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463152","ankiGuid":"cWF{1xN=ql"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-9d0c1616e6f3696a","number":"0257e","sourceNumber":"0257e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Uma mulher de 32 anos de idade queixa-se de acne e aumento de pelos. A avaliação clínica mostra índice de Ferriman e Gallwey de 9. A dosagem de sulfato de dehidroepiandrosterona é elevada, o que sugere que a causa do problema esteja:","options":{"A":"na suprarrenal.","B":"no ovário.","C":"no hipotálamo.","D":"na adenoipófise.","E":"na neuroipófise."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463153","ankiGuid":"nY.[SUrd?b"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-0b04b795d752c0cd","number":"0258e","sourceNumber":"0258e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 25 anos procura atendimento ginecológico com queixa de irregularidade menstrual há 3 anos, apresentando ciclos com intervalos variáveis de 25 a 60 dias, com duração de 6-7 dias e volume moderado. Nega outras queixas. Nega doenças crônicas. Ao exame físico: PA = 120 x 80 mmHg; IMC = 27 kg/m². Exame ginecológico sem alterações, com trofismo genital preservado. Qual o melhor conjunto de exames para a propedêutica complementar?","options":{"A":"Prolactina, LH e Progesterona.","B":"FSH, LH e Estradiol.","C":"FSH, Prolactina e TSH.","D":"TSH, Estradiol e Progesterona."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463154","ankiGuid":"du((0g6Egy"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-4ba3689297891164","number":"0259e","sourceNumber":"0259e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Não faz parte da chamada Síndrome de HAIR-AN:","options":{"A":"Hiperandrogenismo.","B":"Hipertiroidismo.","C":"Aumento da Resistência Insulínica.","D":"Síndrome dos Ovários Policísticos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463155","ankiGuid":"lpPeEoINfM"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-f903e29c56be8390","number":"0260e","sourceNumber":"0260e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 13 anos, refere irregularidade menstrual, com ciclos menstruais de 65 dias, fluxo intenso, presença de acne e hirsutismo. Refere Menarca aos 10 anos, nuligesta. Qual a sua hipótese diagnóstica e qual exame complementar você pediria para confirmar o diagnóstico?","options":{"A":"Infertilidade e dosagens hormonais","B":"Amenorreia Secundária e ultrassom pélvico","C":"Irregularidade menstrual própria da idade e dosagem plasmática de LH e FSH","D":"Síndrome dos ovários policísticos e ultrassom pélvico"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463156","ankiGuid":"op9/P.e.xz"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-37e1177c0d54891c","number":"0261e","sourceNumber":"0261e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"O diagnóstico de síndrome do ovário policístico requer a presença de:","options":{"A":"hipoandrogenemia","B":"oligomenorreia","C":"hipoinsulinemia","D":"emagrecimento"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463157","ankiGuid":"F1rgu)u|Zb"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-5c9b627e39275476","number":"0262e","sourceNumber":"0262e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A Síndrome dos Ovários Policísticos (SOP) é desordem endócrina mais comum nas mulheres em idade reprodutiva, afetando 4-12% das mulheres. A SOP reveste-se de importância não só pela sua frequência, mas também pelas repercussões à saúde como: obesidade, infertilidade, resistência insulínica, dislipidemia, diabetes gestacional, diabetes mellitus tipo 2, depressão e redução da qualidade de vida. Sobre a fisiopatologia da SOP, marque a opção ERRADA:","options":{"A":"Anovulação é consequência de uma inapropriada liberação de GnRH, o que leva a uma maior produção de LH e menor liberação de FSH.","B":"A insulina é capaz de aumentar a produção de globulina carreadora de hormônios sexuais, com isso, aumenta a quantidade total de androgênios circulantes.","C":"Insulina e LH estimulam a produção de androgênios nas células da Teca, como resultado, os ovários produzem níveis elevados de testosterona e androstenediona.","D":"O aumento da estrona é fruto de uma maior conversão periférica pela aromatase, transformando androstenediona em estrona."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463158","ankiGuid":"IA.@R=<PQ:"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-34556667f0aaf2f3","number":"0263e","sourceNumber":"0263e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A síndrome dos ovários policísticos (SOP) acomete 5 a 10% das mulheres em idade reprodutiva. Além de infertilidade, as pacientes com SOP podem apresentar outros problemas listados a seguir, EXCETO:","options":{"A":"Aumento do risco de aterosclerose","B":"Aumento do risco de síndrome metabólica","C":"Aumento do risco de câncer de colo uterino","D":"Aumento do risco de câncer de endométrio"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463159","ankiGuid":"GHwEZ=A-@c"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-1036c2bd32c6163a","number":"0264e","sourceNumber":"0264e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A Síndrome dos Ovários Policísticos (SOP) ou anovulação crônica por retrocontrole impróprio é uma endocrinopatia comum no menacme, acometendo até uma em cada cinco mulheres em idade reprodutiva. A SOP reveste-se de importância não só pelas suas manifestações clínicas, mas também pelas repercussões à saúde ao longo da vida da paciente. Paciente 25 anos procura unidade de saúde queixando-se de atraso menstrual há 2 meses. Está tentando engravidar há 1 ao e refere ciclos irregulares, com intervalos maiores que 45 dias., É realizado um B-HCG cujo resultado é negativo. O médico que a atendeu resolve então solicitar um ultrassom onde foi visibilizado um útero de tamanho normal, endométrio medindo 10mm, ovários com volume aumentado e com mais de 12 folículos cada.Paciente possui IMC 32, não apresenta acne ou hirsutismo. Em relação ao caso clínico assinale a alternativa CORRETA:","options":{"A":"Pode-se afirmar prontamente que essa paciente tem a Síndrome dos ovários policísticos","B":"A relação LH/FSH menor que 2 fechará o diagnóstico de Síndrome dos ovários policísticos","C":"É necessário solicitar TSH, Prolactina, Testosterona, SDHEA e 17-hidroxiprogesterona antes de dar o diagnóstico de Síndrome dos ovários policísticos","D":"A melhor opção para essa paciente engravidar é fazer uso de anticoncepcional oral para diminuir os foliculos ovarianos","E":"Dieta e exercícios físicos não auxiliam no tratamento da Síndrome dos ovários policísticos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463160","ankiGuid":"ftjBb~x5Q#"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-48455c86b9868423","number":"0265e","sourceNumber":"0265e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente, 16 anos, procura atendimento médico com queixa de acne e crescimento de pelos na face e no abdome desde a menarca. Interrompeu uso de anticoncepcional oral há 6 meses e, desde então, vem apresentando ganho ponderal e irregularidade menstrual com oligomenorreia. O exame físico revelou IMC (Índice de Massa Corpórea) de 29kg/m², acne moderada e hirsutismo, sem outras alterações. Quais exames complementares são essenciais para a investigação diagnóstica?","options":{"A":"Ultrassonografia pélvica, beta HCG, testosterona livre.","B":"TSH, prolactina, 17-hidroxiprogesterona.","C":"FSH, estradiol e sulfato de dehidroepiandrosterona.","D":"Ressonância magnética e cortisol urinário."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463161","ankiGuid":"LJeV=!Ti@x"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-f3f22469d296c1e9","number":"0266e","sourceNumber":"0266e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Em paciente de 22 anos apresentando hiperandrogenismo grave/acentuado; resistência insulínica grave, calvície temporal, engrossamento de voz e acantose nigricante podemos relacionar ao diagnóstico de:","options":{"A":"Testículo feminizante.","B":"Tumor de ovário associado a metástase de supra renal.","C":"Síndrome de Hairan.","D":"Síndrome de Klienefelter."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463162","ankiGuid":"d=9y@)gL-d"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-91d47785d2084c61","number":"0267e","sourceNumber":"0267e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente feminina, 25 anos, com quadro clínico sugestivo de síndrome de ovários micropolicísticos. Usa anticoncepcional há 3 anos e vem para consulta de rotina. Qual a melhor conduta para essa paciente?","options":{"A":"Solicitar FSH e LH para avaliar o eixo hipotálamo-hipófise-ovário.","B":"Orientar sobre manutenção de peso adequado e praticar exercícios físicos rotineiramente.","C":"Associar metformina para prevenção da anovulação crônica mesmo com taxas glicêmicas normais.","D":"Parar o anticoncepcional devido ao uso prolongado, sem necessidade de outro contraceptivo devido a associação com infertilidade."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463163","ankiGuid":"QbwvGCXli7"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-3f70fc4957f9e1d9","number":"0268e","sourceNumber":"0268e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Como é feito o diagnóstico da síndrome dos ovários policísticos, de acordo com os critérios de Rotterdam (2003)?","options":{"A":"Oligo-ovulação ou anovulação, hiperandrogenismo e ovários policísticos (todos têm que estar presentes).","B":"Oligo-ovulação ou anovulação, hiperandrogenismo e ovários policísticos (pelo menos dois devem estar presentes).","C":"Aumento da resistência periférica à insulina, hiperandrogenismo e ovários policísticos (todos têm que estar presentes).","D":"Aumento da resistência periférica à insulina, hipertricose e ovários policísticos (pelo menos dois devem estar presentes).","E":"Hiperandrogenismo, ovários micropolicísticos e aumentados, obesidade e hiperprolactinemia (pelo menos dois devem estar presentes)."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463164","ankiGuid":"DFMa-c{Srp"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-87ec3164d5da18f6","number":"0269e","sourceNumber":"0269e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A dosagem elevada de 17-hidroxiprogesterona (acima de 1.000 ng/dl) revela a seguinte causa de hirsutismo:","options":{"A":"Hiperplasia adrenal congênita.","B":"Hipertecose.","C":"Síndrome dos ovários policísticos.","D":"Tumor ovariano.","E":"Doença de Cushing."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463165","ankiGuid":"vn+=dwld2^"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-5c5f03e72243b8aa","number":"0270e","sourceNumber":"0270e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Em relação à síndrome dos ovários policísticos, podemos afirmar que:","options":{"A":"É caracterizada pela presença de múltiplos folículos nos ovários e níveis aumentados de LH.","B":"É uma síndrome comum em idade reprodutiva, porém só cursa com sintomatologia em casos com índice de massa corporal alto.","C":"Os quadros de oligomenorreia e amenorreia podem cursar com hiperplasia de endométrio e aumento do risco de carcinoma endometrial.","D":"O percentual de ciclos ovulatórios aumenta proporcionalmente com os índices de massa corporal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463166","ankiGuid":"NudwP%wM/b"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-5e262a889d6322a8","number":"0271e","sourceNumber":"0271e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Considere os achados abaixo. I - Miométrio heterogêneo; II - Endométrio atrófico; III - Ovários com volume aumentado e com múltiplos folículos desenvolvidos. Quais deles uma paciente com síndrome dos ovários policísticos, em uso contínuo de anticoncepcional oral combinado há 2 anos, apresentaria à ultrassonografia?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463167","ankiGuid":"tmBO.q.Q<w"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-6441c7c98af5c2a0","number":"0272e","sourceNumber":"0272e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 22 anos, nuligesta, refere ciclos oligomenorreicos desde a menarca, que ocorreu aos 12 anos de idade. Apresenta diagnóstico prévio de síndrome dos ovários policísticos. Ao exame, evidencia-se hirsutismo moderado e um Índice de Massa Corporal (IMC) de 31 kg/m². Em relação a esse caso clínico, analise as assertivas a seguir: I. Se a paciente não deseja engravidar, deve-se prescrever anticoncepcional combinado oral para proteção do endométrio e melhora do hirsutismo; II. Deve-se indicar atividade física e rastrear síndrome metabólica. Se houver hiperinsulinismo, está indicada prescrição de metformina; III. É recomendada a redução de peso corporal para a saúde metabólica e restauração dos ciclos ovulatórios. Se for necessária indução da ovulação, o citrato de clomifeno é a droga de escolha; IV. Nessa paciente, encontraremos níveis séricos de progesterona baixo, globulina ligadora de hormônios sexuais (SHBG) diminuída e 17-OH progesterona elevado. Quais estão CORRETAS?","options":{"A":"Apenas I e II.","B":"Apenas II e IV.","C":"Apenas III e IV.","D":"Apenas I, II e III.","E":"I, II, III e IV."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463168","ankiGuid":"NeS1DenEJX"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-cb0599cd2048fca1","number":"0273e","sourceNumber":"0273e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Analise os fatores abaixo relacionados à fisiopatologia da síndrome dos ovários policísticos: I. Estimulação da esteroidogênese ovariana pela insulina. II. Estimulação da síntese hepática de SHBG pela insulina. III. Níveis elevados de estrona, devido à conversão periférica. IV. Menor sensibilidade hipofisária ao GnRH na secreção de LH. Quais estão corretas?","options":{"A":"Apenas I e II.","B":"Apenas I e III.","C":"Apenas II e III.","D":"Apenas II e IV.","E":"Apenas I, II e IV."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463169","ankiGuid":"lyk%Jt&7E1"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-c7a511867c9e84c6","number":"0274e","sourceNumber":"0274e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 35 anos, com diagnóstico de ovários policísticos, apresenta placas acastanhadas nas virilhas, axilas e sulcos inframamários, sinais clínicos de:","options":{"A":"Aumento de prolactina.","B":"Aumento de 21-hidroxilase.","C":"Hiperandrogenismo.","D":"Resistência à insulina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463170","ankiGuid":"z*Yalb80=c"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-6b9cfe37a4a4bfa9","number":"0275e","sourceNumber":"0275e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Jovem, com 24 anos de idade, apresenta ciclos menstruais irregulares, com atrasos menstruais frequentes, oleosidade da pele, acantose nigrans e hirsutismo leve em região mentoniana. Exame ecográfico demonstra características compatíveis com ovários micropolicísticos bilateralmente. A observação correta em relação ao seguimento e ao tratamento dessa paciente é:","options":{"A":"A recomendação de perda de peso, de atividade física e de alimentação rica em fibra deve ser restrita aos casos de ganho de peso recente.","B":"A regularização do ciclo e o uso de citrato de clomifeno são as escolhas iniciais preferenciais caso a paciente tenha desejo de engravidar.","C":"A paciente deve ser alertada para a possibilidade de maior risco cardiovascular por alterações no perfil lipídico e maior risco oncogênico, principalmente para endométrio.","D":"A utilização de anticoncepcional hormonal oral não é indicada, pois não melhora o hirsutismo, a acne e não regulariza o intervalo menstrual."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463171","ankiGuid":"C$u)e~do2T"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-15468538a0b5acfd","number":"0276e","sourceNumber":"0276e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Segundo os critérios de Roterdam (2003), diagnostica-se a síndrome dos ovários policísticos quando se verifica a presença de mais de 12 folículos menores de 9 mm em cada ovário e hirsutismo. Além disso, deve-se considerar a existência de:","options":{"A":"Oligomenorreia.","B":"Intolerância a glicose.","C":"Hipomenorreia.","D":"Resistência a insulina.","E":"Hiperandrogenismo."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463172","ankiGuid":"bWzL|@[-}8"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-4665f2f976e8983c","number":"0277e","sourceNumber":"0277e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Na síndrome do ovário policístico é CORRETO afirmar:","options":{"A":"Para definir a síndrome a paciente deve apresentar disfunção menstrual, hiperandrogenismo, hirsutismo e ovários policísticos ao ultrassom.","B":"A pontuação de Ferriman-Gallwey pode ser utilizada para avaliar o grau de acne.","C":"O procedimento de perfuração ovariana por via laparoscópica recupera a ovulação em um significativo de mulheres com SOP resistentes ao citrato de clomifeno.","D":"O tratamento de primeira linha para irregularidades na menstruação é o uso de agentes insulino-sensibilizantes.","E":"Todas as alternativas estão corretas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463173","ankiGuid":"m.XPN%v1.t"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-1ca601274b5604e8","number":"0278e","sourceNumber":"0278e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Na síndrome dos ovários policísticos, podemos afirmar: I – A visualização de microcistos ovarianos múltiplo ao Ultrassom (USG) é suficiente para estabelecer o diagnóstico. II – O aumento de androgênios leva ao aumento de estradiol por ação da aromatase. III – Androgênios aumentados, além da diminuição de SHBG, elevam a testosterona livre e o hirsutismo. Estão CORRETAS apenas:","options":{"A":"I e II.","B":"II e III.","C":"I e III.","D":"III."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463174","ankiGuid":"h.M!%_^FuO"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-be41b67c3ecb2a1f","number":"0279e","sourceNumber":"0279e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A Síndrome dos Ovários Policísticos (SOP) é um distúrbio no eixo neuroendócrino reprodutor, associado à alteração morfológica ovariana e à produção androgênica elevada. A característica mais marcante nesta afecção é o hiperandrogenismo associado ao estado de anovulação crônica que, também, pode ser encontrado em outras doenças. Em relação ao diagnóstico diferencial de SOP e a deficiência de 21-hidroxilase de manifestação tardia, o exame auxiliar mais importante é a dosagem de:","options":{"A":"17-hidroxiprogesterona.","B":"Testosterona.","C":"Cortisol.","D":"Deidroepiandrosterona."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463175","ankiGuid":"xsy;<nI!NC"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-24161b494034da75","number":"0280e","sourceNumber":"0280e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Observe as afirmativas abaixo e assinale qual não está relacionada à Síndrome dos Ovários Policísticos (SOP):","options":{"A":"Aumento do risco relativo para câncer de mama.","B":"Aumento do risco relativo para diabetes.","C":"Aumento do risco relativo para câncer de ovário.","D":"Aumento do risco relativo para doenças cardiovasculares.","E":"Aumento do risco relativo para câncer de endométrio."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463176","ankiGuid":"vSQtNO,gBY"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-4462cd3ad0630d1d","number":"0281e","sourceNumber":"0281e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 22 anos atendida com amenorréia primária, hirsutismo e dosagens elevadas de testosterona total, sulfato de dehidroepiandrosterona (SDHEA) e 17- hidroxiprogesterona. Qual a principal hipótese diagnóstica?","options":{"A":"Tumor ovariano produtor de androgênios.","B":"Tumor de supra-renal.","C":"Macroadenoma hipofisário.","D":"Hiperplasia congênita da supra-renal.","E":"Síndrome dos Ovários Policísticos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463177","ankiGuid":"gaB.:U^$6"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-ed0e5a3e581d39d1","number":"0282e","sourceNumber":"0282e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Mulher de 25 anos de idade refere ter menstruação irregular, com intervalos superiores a 6 meses desde a menarca. Refere ter dificuldade para emagrecer e vem notando pele oleosa e manchas escuras na pele. Ao exame, observa-se índice de Ferriman de 14. Nas regiões de dobras existe coloração marrom da pele. O IMC é de 30 kg/m². O diagnóstico é de:","options":{"A":"Insuficiência ovariana de causa lúpica.","B":"Disgenesia gonadal pura.","C":"Síndrome de feminização testicular.","D":"Síndrome dos ovários policísticos com resistência insulínica.","E":"Síndrome da resistência androgênica periférica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463178","ankiGuid":"jWEa{#gC:N"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-e663ad004976ee5e","number":"0283e","sourceNumber":"0283e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Com relação à síndrome dos ovários policísticos na adolescência, assinale a alternativa INCORRETA","options":{"A":"Há irregularidade menstrual.","B":"Presença de acne e hirsutismo.","C":"Confirmação diagnóstica pela ultrassonografia pélvica, TC de crânio, dosagem de gonadotrofinas.","D":"Além dos cistos ovarianos, existe oligo/anovulação.","E":"Existe maior chance de desenvolver síndrome metabólica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463179","ankiGuid":"q<;*3ths,2"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-bdbd9e3aa80b7447","number":"0284e","sourceNumber":"0284e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 24 anos, nuligesta, DUM = há 45 dias, procura atendimento ginecológico, pois está muito incomodada com o aumento de pelos em face, abdome e pernas, que piorou há 2 anos. Além disso, refere irregularidade menstrual desde a menarca. Também apresentou ganho de peso importante com aumento de 20 quilos nos últimos 3 anos. Nega outras queixas. Refere vida sexual ativa, em uso regular de preservativo como método contraceptivo. Nega vícios ou outras doenças concomitantes. Ao exame físico: BEG; corada; peso = 81 kg; altura = 1,65 m; IMC = 29,75 kg/m²; PA = 120 x 80 mmHg; FC = 88 bpm; CA = 98 cm. Índice de Ferriman-Gallwey = 13. Exame físico das mamas e ginecológico: sem alterações. Foram solicitados exames hormonais para diagnóstico: TSH = 2,2 mlU/ml (VN = 0,5 a 4,0 mlU/ml); FSH = 3,1 mlU/ml (VN = 2,8 a 10, 5 mlU/ml); prolactina = 18,0 ng/ml (VN < 25,0 ng/ml); testosterona = 118 ng/dl (VN < 80 ng/dl); 17OH-progesterona = 78 ng/dl (VN < 150 ng/dl); DHEA-S = 101 g/dl (VN < 350 µg/dl). Lipidograma normal e TOTG em tempo 0 = 89 mg/dl e em tempo 120min = 130 mg/dl. US transvaginal = útero AVF com 98 cm³; eco endometrial = 7 mm de espessura; Ovário D = 11,2 cm³, com 14 folículos antrais iniciais e Ovário E = 8,8 cm³, com 10 folículos antrais iniciais. A melhor conduta para o controle da doença, nesse caso, é prescrever:","options":{"A":"Metformina, pois a melhora da intolerância à glicose reduzirá o distúrbio metabólico.","B":"Contraceptivo combinado oral para melhora do hiperandrogenismo clínico.","C":"Progestógeno de segunda fase para controle do ciclo menstrual.","D":"Espironolactona entre o 5° e o 14° dia do ciclo, associado à orientação de dieta e atividade física."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463180","ankiGuid":"m}^/b|Z2V2"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-c6e8719d5efa9f89","number":"0285e","sourceNumber":"0285e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 33 anos consultou para investigação de infertilidade. Relatou estar tentando engravidar há 2 anos e não fazer uso de medicações. Referiu menstruações regulares apenas quando utilizou anticoncepcional oral. Investigação prévia já descartara hiperplasia adrenal congênita. Encontrava-se há 4 meses sem menstruar, tendo a última menstruação ocorrido após 5 dias de uso de progesterona. O teste de gestação realizado há 3 dias foi negativo. Apresentava acne discreta. O índice de Ferriman era de 13, e o IMC, de 31 kg/m². Considere as alterações hormonais e metabólicas abaixo. I - Hipoestrogenismo e hiperinsulinemia; II - Níveis de progesterona baixo e de SHBG diminuído; III-Hiperandrogenismo e nível de 17-OH-progesterona normal. Quais delas são esperadas nessa paciente?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463181","ankiGuid":"s5pQ`rmhVw"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-febed53250d5a1b4","number":"0286e","sourceNumber":"0286e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Paciente de 22 anos, menarca aos 13 anos, queixa-se de que há aproximadamente um ano apresenta amenorreia associada a crescimento de pelos onde antes não existiam e ganho de peso. Ao exame, constata-se hirsutismo. Para caracterizar a síndrome dos ovários policísticos nessa paciente é necessário:","options":{"A":"Dosagem sérica de insulina.","B":"Confirmar presença dos ovários policísticos na ultrassonografia, pois a ausência deste exclui diagnóstico.","C":"Dosagem sérica de testosterona para confirmar hiperandrogenismo.","D":"Afastar outras causas de oligomenorreia e hiperandrogenismo.","E":"Não é possível caracterizar síndrome dos ovários policísticos nesta paciente, pois o quadro clínico é incompatível."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463182","ankiGuid":"l!q[5~QZUI"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-3dab0ccc1af6131f","number":"0287e","sourceNumber":"0287e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Em relação ao Defeito Primário Neuroendócrino da SOP (Síndrome dos Ovários Policísticos) analise as assertivas: I. Ocorre um aumento da frequência e do pulso de LH. II. As células da teca aumentam a produção de andrógenos. III. Os andrógenos são convertidos em estrógenos na granulosa ou em tecidos periféricos. IV. O Estrogênio estimula a Hipófise a liberar LH, promove feedback negativo no FSH, causando maturação incompleta do folículo. Indique a alternativa CORRETA.","options":{"A":"Somente as assertivas I, II e III estão corretas.","B":"Somente as assertivas I e II estão corretas.","C":"Somente as assertivas I e III estão corretas.","D":"Somente as assertivas III e IV estão corretas.","E":"Todas as assertivas estão corretas."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463183","ankiGuid":"ydDS4ZA?!J"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-39b74e89ed390ff8","number":"0288e","sourceNumber":"0288e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"Uma paciente de 18 anos, menarca aos 11 anos, apresenta ciclos menstruais oligomenorreicos com períodos de amenorreia e hirsutismo severo ao exame e obesidade. Para caracterizar a Síndrome dos Ovários Policísticos (SOP) nessa paciente, é necessário:","options":{"A":"Confirmar a resistência insulínica com dosagem de insulina.","B":"Excluir outras causas de anovulação e hiperandrogenismo.","C":"Confirmar o hiperandrogenismo com dosagem de testosterona.","D":"Identificar a presença dos dois ovários aumentados ao ultrassom, pois ovários normais excluem SOP.","E":"Confirmar a síndrome metabólica."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463184","ankiGuid":"b9i!dRbtIL"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-63a021e40f931d8e","number":"0289e","sourceNumber":"0289e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"A falta de menstruação é um sintoma comum que pode atingir até 5% das mulheres. A amenorreia é apenas um sintoma de várias entidades clínicas possíveis. Sendo assim, analise o caso clínico abaixo: Paciente de 22 anos, universitária marcou consulta devido à irregularidade menstrual e traz consigo alguns exames laboratoriais. Refere ciclos menstruais \"espaçados\", com períodos de ausência de menstruação por até 4 meses. Relata menarca aos 13 anos e nega coitarca. Queixa-se de excesso de pelos nos membros e tórax e acne na face. Ao exame: IMC: 30,5 kg/m², oleosidade excessiva na pele, escore de Ferrimam-Gallwey modificado de 6, acne grau I. TSH T4 livre, prolactina, testoterona total e livre, androstenediona, 17-OH-progesterona, DHEA e SDHEA são normais. Glicemia de jejum de 103 mg/dl. Qual é a opção terapêutica inicial mais indicada para o caso?","options":{"A":"Espironolactona.","B":"Flutamida.","C":"Mudanças do estilo de vida e perda de peso.","D":"Acetato de medroxiprogesterona de depósito","E":"Inibidor da 5 alfa-redutase."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463185","ankiGuid":"ot.=<[Pyk:"},{"id":"anki-ginecologia-sindrome-dos-ovarios-policisticos-9d7f6f542fdf55c2","number":"0290e","sourceNumber":"0290e","collectionBlock":"anki:ginecologia-sindrome-dos-ovarios-policisticos","collectionLabel":"Anki · Síndrome dos Ovários Policísticos","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Síndrome dos Ovários Policísticos","subtopic":"","stem":"L.C.C, 18 anos, nuligesta, com vida sexual ativa, porém sem parceiro fixo, com ciclos irregulares desde a menarca (4/45-60), deseja fazer uso de um método anticoncepcional. Ao exame físico: mamas normais, presença de acne, aumento da pilificação em regiões de buço, abdome inferior e região posterior das coxas. IMC: 28. Exames complementares: citologia oncótica: inflamatório moderado por cocos, negativo para neoplasia; USTV: útero em AVF, medindo 4,0 x 3,5 x 3,0 cm, ovários normais. Qual o melhor método?","options":{"A":"Etinilestradiol + levonorgestrel.","B":"Etinilestradiol + drospirenona.","C":"Desogestrel + preservativo.","D":"Preservativo.","E":"DIU."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Síndrome dos Ovários Policísticos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Síndrome dos Ovários Policísticos","Anki"],"ankiNoteId":"1779711463186","ankiGuid":"GJ%qXL(iad"}]};
